#!/usr/bin/env python3
"""Flask + Socket.IO app with Orion CRUD proxy and real-time notifications."""

from datetime import datetime, timezone
import logging
import os
import re
from typing import Any
from urllib.parse import quote
from uuid import uuid4

import requests
from flask import Flask, jsonify, render_template, request
from flask_cors import CORS
from flask_socketio import SocketIO, emit

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

# Flask app setup
app = Flask(__name__)
app.config["SECRET_KEY"] = os.environ.get("SECRET_KEY", "dev-secret-key-change-in-production")
CORS(app, resources={r"/*": {"origins": "*"}})
socketio = SocketIO(app, cors_allowed_origins="*")

# Orion config
ORION_URL = os.environ.get("ORION_URL", "http://localhost:1026").rstrip("/")
ORION_HEADERS = {"Accept": "application/json"}
ORION_LIST_LIMIT = int(os.environ.get("ORION_LIST_LIMIT", "1000"))
STORE_QUERY_ATTRS = (
    "name,address,location,url,telephone,countryCode,capacity,description,"
    "temperature,relativeHumidity,tweets,image"
)
CONTEXT_PROVIDER_REGISTRATION_TEMPLATES: list[dict[str, Any]] = [
    {
        "description": "App bootstrap weather conditions for all stores",
        "dataProvided": {
            "attrs": ["temperature", "relativeHumidity"],
        },
        "provider": {
            "http": {"url": "http://tutorial:3000/random/weatherConditions"},
            "legacyForwarding": True,
        },
        "status": "active",
    },
    {
        "description": "App bootstrap tweets for all stores",
        "dataProvided": {
            "attrs": ["tweets"],
        },
        "provider": {
            "http": {"url": "http://tutorial:3000/catfacts/tweets"},
            "legacyForwarding": True,
        },
        "status": "active",
    },
]
LEGACY_PROVIDER_DESCRIPTIONS = {
    "Weather conditions for all stores",
    "Tweets for all stores",
}

# Runtime state
connected_clients: dict[str, dict[str, Any]] = {}
VALID_SIZES = {"XS", "S", "M", "L", "XL"}
VALID_SKILLS = {"MachineryDriving", "WritingReports", "CustomerRelationships"}
VALID_EMPLOYEE_CATEGORIES = {"Manager", "Warehouse", "Sales", "CustomerSupport"}
USERNAME_RE = re.compile(r"^[A-Za-z0-9_]+$")
HEX_COLOR_RE = re.compile(r"^#[0-9A-Fa-f]{6}$")


def utc_iso() -> str:
    """Return timezone-aware UTC timestamp."""
    return datetime.now(timezone.utc).isoformat()


def api_error(message: str, status: int = 400, field_errors: dict[str, str] | None = None):
    payload = {"status": "error", "message": message}
    if field_errors:
        payload["fieldErrors"] = field_errors
    return jsonify(payload), status


def orion_request(method: str, path: str, payload: dict | None = None, params: dict | None = None):
    """Execute request to Orion and return the raw response."""
    url = f"{ORION_URL}{path}"
    headers = dict(ORION_HEADERS)
    if method.upper() in {"POST", "PATCH", "PUT"}:
        headers["Content-Type"] = "application/json"

    response = requests.request(
        method=method,
        url=url,
        headers=headers,
        json=payload,
        params=params,
        timeout=10,
    )
    return response


def sanitize_employee(entity: dict[str, Any]) -> dict[str, Any]:
    """Hide sensitive fields from employee responses."""
    if "password" in entity:
        entity["password"] = "********"
    return entity


def parse_orion_error(response: requests.Response) -> str:
    try:
        body = response.json()
        return body.get("description") or body.get("error") or response.text
    except Exception:
        return response.text or "Unknown Orion error"


def ensure_context_provider_registrations() -> None:
    """Register external Store providers once at startup (idempotent by description)."""
    try:
        stores_response = orion_request("GET", "/v2/entities", params={"type": "Store", "options": "keyValues"})
        if stores_response.status_code >= 400:
            logger.warning("Could not list Stores for provider registration: %s", parse_orion_error(stores_response))
            return

        stores_payload = stores_response.json()
        store_entities = [
            {"id": item.get("id"), "type": "Store"}
            for item in stores_payload
            if isinstance(item, dict) and item.get("id")
        ]
        if not store_entities:
            logger.warning("No Store entities found; skipping context provider registration")
            return

        existing_response = orion_request("GET", "/v2/registrations")
        if existing_response.status_code >= 400:
            logger.warning("Could not list Orion registrations: %s", parse_orion_error(existing_response))
            return

        existing = existing_response.json()
        existing_by_description = {
            item.get("description", ""): item
            for item in existing
            if isinstance(item, dict) and item.get("description")
        }

        # Remove legacy registrations created with wrong provider URLs.
        for description in LEGACY_PROVIDER_DESCRIPTIONS:
            reg = existing_by_description.get(description)
            if not reg:
                continue
            reg_id = reg.get("id")
            if not reg_id:
                continue
            delete_response = orion_request("DELETE", f"/v2/registrations/{reg_id}")
            if delete_response.status_code >= 400:
                logger.warning("Failed deleting legacy registration '%s': %s", description, parse_orion_error(delete_response))
            else:
                logger.info("Legacy registration deleted: %s", description)

        for template in CONTEXT_PROVIDER_REGISTRATION_TEMPLATES:
            registration = {
                "description": template["description"],
                "dataProvided": {
                    "entities": store_entities,
                    "attrs": template["dataProvided"]["attrs"],
                },
                "provider": template["provider"],
                "status": template["status"],
            }
            description = registration.get("description", "")
            current = existing_by_description.get(description)
            if current:
                current_url = current.get("provider", {}).get("http", {}).get("url")
                current_attrs = current.get("dataProvided", {}).get("attrs", [])
                current_ids = [
                    ent.get("id")
                    for ent in current.get("dataProvided", {}).get("entities", [])
                    if isinstance(ent, dict) and ent.get("id")
                ]
                expected_url = registration.get("provider", {}).get("http", {}).get("url")
                expected_attrs = registration.get("dataProvided", {}).get("attrs", [])
                expected_ids = [ent.get("id") for ent in store_entities]

                same_url = current_url == expected_url
                same_attrs = sorted(current_attrs) == sorted(expected_attrs)
                same_ids = sorted(current_ids) == sorted(expected_ids)
                if same_url and same_attrs and same_ids:
                    logger.info("Context provider already registered: %s", description)
                    continue

                reg_id = current.get("id")
                if reg_id:
                    delete_response = orion_request("DELETE", f"/v2/registrations/{reg_id}")
                    if delete_response.status_code >= 400:
                        logger.warning("Failed replacing registration '%s': %s", description, parse_orion_error(delete_response))
                        continue
                    logger.info("Context provider registration replaced: %s", description)

            response = orion_request("POST", "/v2/registrations", payload=registration)
            if response.status_code >= 400:
                logger.warning(
                    "Failed to register context provider '%s': %s",
                    description,
                    parse_orion_error(response),
                )
                continue

            logger.info("Context provider registered: %s", description)
    except requests.RequestException as exc:
        logger.warning("Orion unavailable while registering context providers: %s", str(exc))


def validate_product(data: dict[str, Any], partial: bool = False) -> tuple[bool, dict[str, str]]:
    errors: dict[str, str] = {}
    required_fields = ["name", "color", "size", "price"]

    if not partial:
        for field in required_fields:
            if field not in data:
                errors[field] = "Field is required"

    if "name" in data:
        value = str(data.get("name", "")).strip()
        if len(value) < 2:
            errors["name"] = "Name must have at least 2 characters"

    if "color" in data:
        value = str(data.get("color", "")).strip()
        if not HEX_COLOR_RE.match(value):
            errors["color"] = "Color must be in hexadecimal format #RRGGBB"

    if "size" in data:
        value = str(data.get("size", "")).strip().upper()
        if value not in VALID_SIZES:
            errors["size"] = "Size must be one of XS, S, M, L, XL"

    if "price" in data:
        try:
            price = int(data.get("price"))
            if price < 1:
                errors["price"] = "Price must be greater than 0"
        except (TypeError, ValueError):
            errors["price"] = "Price must be an integer"

    if "image" in data and data.get("image"):
        value = str(data.get("image", "")).strip()
        if not (value.startswith("http://") or value.startswith("https://")):
            errors["image"] = "Image must be a valid URL"

    return len(errors) == 0, errors


def validate_employee(data: dict[str, Any], partial: bool = False) -> tuple[bool, dict[str, str]]:
    errors: dict[str, str] = {}
    required_fields = [
        "name",
        "email",
        "dateOfContract",
        "category",
        "skills",
        "username",
        "refStore",
    ]

    if not partial:
        for field in required_fields:
            if field not in data:
                errors[field] = "Field is required"
        if "password" not in data:
            errors["password"] = "Password is required"

    if "name" in data:
        value = str(data.get("name", "")).strip()
        if len(value) < 2:
            errors["name"] = "Name must have at least 2 characters"

    if "email" in data:
        value = str(data.get("email", "")).strip()
        if "@" not in value or "." not in value.split("@")[-1]:
            errors["email"] = "Email must be valid"

    if "dateOfContract" in data:
        value = str(data.get("dateOfContract", "")).strip()
        if len(value) < 10:
            errors["dateOfContract"] = "Date must use YYYY-MM-DD format"

    if "skills" in data:
        skills = data.get("skills", [])
        if not isinstance(skills, list) or not skills:
            errors["skills"] = "At least one skill is required"
        else:
            invalid = [s for s in skills if s not in VALID_SKILLS]
            if invalid:
                errors["skills"] = "Invalid skills detected"

    if "category" in data:
        value = str(data.get("category", "")).strip()
        if value not in VALID_EMPLOYEE_CATEGORIES:
            errors["category"] = "Invalid category"

    if "username" in data:
        value = str(data.get("username", "")).strip()
        if len(value) < 3:
            errors["username"] = "Username must have at least 3 characters"
        elif not USERNAME_RE.match(value):
            errors["username"] = "Username only supports letters, numbers, and _"

    if "password" in data and data.get("password"):
        value = str(data.get("password", ""))
        if len(value) < 8:
            errors["password"] = "Password must have at least 8 characters"

    if "refStore" in data:
        value = str(data.get("refStore", "")).strip()
        if not value.startswith("urn:ngsi-ld:Store:"):
            errors["refStore"] = "refStore must be a valid Store URN"

    if "image" in data and data.get("image"):
        value = str(data.get("image", "")).strip()
        if not (value.startswith("http://") or value.startswith("https://")):
            errors["image"] = "Image must be a valid URL"

    return len(errors) == 0, errors


def validate_store(data: dict[str, Any], partial: bool = False) -> tuple[bool, dict[str, str]]:
    errors: dict[str, str] = {}
    required_fields = ["name", "countryCode", "temperature", "relativeHumidity"]

    if not partial:
        for field in required_fields:
            if field not in data:
                errors[field] = "Field is required"

    if "name" in data:
        value = str(data.get("name", "")).strip()
        if len(value) < 2:
            errors["name"] = "Name must have at least 2 characters"

    if "countryCode" in data:
        value = str(data.get("countryCode", "")).strip().upper()
        if len(value) != 2:
            errors["countryCode"] = "countryCode must have exactly 2 characters"

    if "temperature" in data:
        try:
            temp = float(data.get("temperature"))
            if temp < -50 or temp > 50:
                errors["temperature"] = "temperature must be between -50 and 50"
        except (TypeError, ValueError):
            errors["temperature"] = "temperature must be numeric"

    if "relativeHumidity" in data:
        try:
            humidity = float(data.get("relativeHumidity"))
            if humidity < 0 or humidity > 100:
                errors["relativeHumidity"] = "relativeHumidity must be between 0 and 100"
        except (TypeError, ValueError):
            errors["relativeHumidity"] = "relativeHumidity must be numeric"

    if "capacity" in data and str(data.get("capacity", "")).strip() != "":
        try:
            capacity = int(data.get("capacity"))
            if capacity < 0:
                errors["capacity"] = "capacity must be >= 0"
        except (TypeError, ValueError):
            errors["capacity"] = "capacity must be an integer"

    if "url" in data and data.get("url"):
        value = str(data.get("url", "")).strip()
        if not (value.startswith("http://") or value.startswith("https://")):
            errors["url"] = "url must be a valid URL"

    if "image" in data and data.get("image"):
        value = str(data.get("image", "")).strip()
        if not (value.startswith("http://") or value.startswith("https://")):
            errors["image"] = "image must be a valid URL"

    if "longitude" in data:
        try:
            longitude = float(data.get("longitude"))
            if longitude < -180 or longitude > 180:
                errors["longitude"] = "longitude must be between -180 and 180"
        except (TypeError, ValueError):
            errors["longitude"] = "longitude must be numeric"

    if "latitude" in data:
        try:
            latitude = float(data.get("latitude"))
            if latitude < -90 or latitude > 90:
                errors["latitude"] = "latitude must be between -90 and 90"
        except (TypeError, ValueError):
            errors["latitude"] = "latitude must be numeric"

    has_lon = "longitude" in data and str(data.get("longitude", "")).strip() != ""
    has_lat = "latitude" in data and str(data.get("latitude", "")).strip() != ""
    if has_lon != has_lat:
        errors["location"] = "longitude and latitude must be provided together"

    return len(errors) == 0, errors


def extract_store_location(data: dict[str, Any]) -> dict[str, Any] | None:
    has_lon = "longitude" in data and str(data.get("longitude", "")).strip() != ""
    has_lat = "latitude" in data and str(data.get("latitude", "")).strip() != ""
    if not (has_lon and has_lat):
        return None
    return {
        "type": "Point",
        "coordinates": [float(data["longitude"]), float(data["latitude"])],
    }


def location_to_lon_lat(location_value: Any) -> dict[str, float] | None:
    if not isinstance(location_value, dict):
        return None
    if location_value.get("type") != "Point":
        return None
    coordinates = location_value.get("coordinates")
    if not isinstance(coordinates, list) or len(coordinates) != 2:
        return None
    try:
        return {
            "longitude": float(coordinates[0]),
            "latitude": float(coordinates[1]),
        }
    except (TypeError, ValueError):
        return None


def build_product_entity(data: dict[str, Any], entity_id: str | None = None) -> dict[str, Any]:
